import{_ as i,l,o as e,c as n,v as t,p as d,x as r,d as D,i as A,S as s}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"存储器光刻：DRAM 与 NAND","description":"","frontmatter":{"title":"存储器光刻：DRAM 与 NAND","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/memory-litho-dram-nand.md","filePath":"litho/memory-litho-dram-nand.md","lastUpdated":1789023840000}'),h={name:"litho/memory-litho-dram-nand.md"};function p(N,a,m,E,c,_){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="存储器光刻-dram-与-nand" tabindex="-1">存储器光刻：DRAM 与 NAND <a class="header-anchor" href="#存储器光刻-dram-与-nand" aria-label="Permalink to &quot;存储器光刻：DRAM 与 NAND&quot;">​</a></h1><div class="epigraph"><p>DRAM 仍在平面上挤半节距，浸没 + 多重是主路径；3D NAND 把负担交给深孔刻蚀，光刻更多是对准与台阶。</p><footer>—— 对照 DRAM 与 3D NAND 图形化负担转移的公开论述</footer></div><p><a href="/litho/foundry-roadmap-compare">上一课</a>对比逻辑代工。缺口是存储。本课钉 DRAM 与 NAND 的光刻角色。3D NAND 负担如何具体转移，留给[下一课](/litho/3d-nand-litho-shift）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DRAM：电容与字线/位线在平面周期上，ArF 浸没加 SADP/SAQP、套刻极严，EUV 插入是成本交叉问题，阵列周期性对掩模 CDU 与热点极敏感。NAND：3D 堆叠后，关键变成沟道孔、台阶、字线切割的深宽比刻蚀与沉积，光刻分辨率压力相对逻辑/DRAM 平面密线不同。</p><p>缺口是<strong>产品类改瓶颈机台</strong>，不是同一套 CPP 故事。把存储 capex 也写成「全是 EUV」，会错。</p><h3 id="阵列-vs-外围" tabindex="-1">阵列 vs 外围 <a class="header-anchor" href="#阵列-vs-外围" aria-label="Permalink to &quot;阵列 vs 外围&quot;">​</a></h3><p>DRAM/NAND 外围逻辑仍可能走类似逻辑的金属光刻；阵列才是产品特征。规划要拆。</p><p><span class="marginnote">存储厂的浸没台数与逻辑厂 mix 完全不同，交叉模型要换输入。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>分阵列/外围列层策略。DRAM 盯半节距与套刻；NAND 盯孔 AR、对准、键合（若有）。EUV 对 DRAM 的交叉按公开插入叙事理解，不编层数。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>比特密度：DRAM 靠平面 F²；NAND 靠层数 × 平面孔密度。后者让刻蚀/薄膜的边际回报在一段时间内高于缩孔节距。光刻仍定义孔位置与套刻，但不总是分辨率英雄。</p>',13)),(e(),d(s,null,{default:r(()=>[A(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20DRAM%5B%22DRAM%20%E9%98%B5%E5%88%97%22%5D%20--%3E%20PITCH%5B%22%E5%B9%B3%E9%9D%A2%E8%8A%82%E8%B7%9D%20%2B%20%E5%A4%9A%E9%87%8D%20%2F%20EUV%22%5D%0A%20%20NAND%5B%223D%20NAND%22%5D%20--%3E%20ETCH%5B%22%E6%B7%B1%E5%AD%94%20%2F%20%E5%8F%B0%E9%98%B6%E5%88%BB%E8%9A%80%22%5D%0A%20%20NAND%20--%3E%20LITH%5B%22%E5%AD%94%E4%BD%8D%E7%BD%AE%20%E5%AF%B9%E5%87%86%20%E5%8F%B0%E9%98%B6%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[D(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不给各厂堆叠层数当永远数。不把 DRAM EUV 插入当已完成或永不。本课不展开电容介质物理。</p><p>后课默认：NAND 的主墙在刻蚀；下一课专门写光刻负担如何转移。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DRAM：平面节距与套刻，浸没多重/EUV 交叉。</li><li>3D NAND：分辨率压力让位于深孔刻蚀，光刻管位置与台阶。</li><li>阵列与外围策略不同。</li><li>出处：DRAM/NAND 图形化负担的公开论述。</li></ul>',5))])}const f=i(h,[["render",p]]);export{B as __pageData,f as default};
